contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function
    // newOwner: address to pass to setOwner
    function run(address newOwner) public payable {
        require(true);

        // Read owner before the tested call
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;

        // Perform the tested call as a top-level statement and capture whether it reverted and any return value
        bool reverted;
        bool returnValue;
        bool rv = c.setOwner(newOwner); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
            returnValue = false;
        } else {
            reverted = false;
            returnValue = rv;
        }

        // Read owner after the call
        address ownerAfter = c.owner(); if (__ESBMC_reverted()) return;

        // Assert the general rule:
        // - If the call did not revert then it must have returned true and ownerAfter equals newOwner.
        // - If the call reverted then ownerAfter must equal ownerBefore (unchanged).
        assert((!reverted && returnValue == true && ownerAfter == newOwner) || (reverted && ownerAfter == ownerBefore));
    }

    receive() external payable {}
}

